export function launchProgress(value,label){const splash=document.getElementById('launch-screen');if(!splash||splash.hidden)return;const progress=splash.querySelector('progress');progress.value=Math.max(progress.value,Math.min(100,value));splash.querySelector('[data-launch-percent]').textContent=Math.round(progress.value)+'٪';if(label)splash.querySelector('[data-launch-label]').textContent=label;}
export async function finishLaunch(){launchProgress(100,'اكتملت التهيئة');await new Promise(resolve=>setTimeout(resolve,180));const splash=document.getElementById('launch-screen');if(splash){splash.hidden=true;splash.setAttribute('aria-busy','false');}}
